#include"lib/vm.h"
#include<stdio.h>
#include<stdlib.h>
#include<string.h>
#include<ctype.h>
typedef enum{TOK_NUM,TOK_STR,TOK_IDENT,TOK_BINOP,TOK_EQ,TOK_EOF,TOK_UNK,TOK_LPAREN,TOK_RPAREN,TOK_COMMA,TOK_DEREF,TOK_STRMETH,TOK_DOT}TT2;
typedef struct{TT2 t;char*v;}Tk2;
static const char*lx;static Tk2 tk;
static Tk2 mk2(TT2 t,const char*s,const char*e){Tk2 tk;tk.t=t;int n=e-s;tk.v=malloc(n+1);memcpy(tk.v,s,n);tk.v[n]=0;return tk;}
static void adv(){while(1){while(*lx==' '||*lx=='\t'||*lx=='\n'||*lx=='\r')lx++;if(*lx=='#'){while(*lx&&*lx!='\n'&&*lx!='\r')lx++;continue;}break;}if(!*lx){tk.t=TOK_EOF;tk.v=strdup("");return;}const char*s=lx;char c=*lx++;if(isdigit(c)||(c=='.'&&isdigit(*lx))){while(isdigit(*lx)||*lx=='.')lx++;tk=mk2(TOK_NUM,s,lx);return;}if(c=='"'){s=lx;while(*lx&&*lx!='"')lx++;tk=mk2(TOK_STR,s,lx);if(*lx=='"')lx++;return;}if(isalpha(c)||c=='_'){while(isalnum(*lx)||*lx=='_')lx++;tk=mk2(TOK_IDENT,s,lx);return;}char n=*lx;if((c=='<'||c=='>'||c=='!')&&n=='='){lx++;tk=mk2(TOK_BINOP,s,lx);return;}if(c=='='&&n=='='){lx++;tk=mk2(TOK_BINOP,s,lx);return;}switch(c){case'=':tk=mk2(TOK_EQ,s,lx);break;case'+':case'-':case'*':case'/':case'%':tk=mk2(TOK_BINOP,s,lx);break;case'<':case'>':tk=mk2(TOK_BINOP,s,lx);break;case'(':tk=mk2(TOK_LPAREN,s,lx);break;case')':tk=mk2(TOK_RPAREN,s,lx);break;case',':tk=mk2(TOK_COMMA,s,lx);break;case'$':tk=mk2(TOK_DEREF,s,lx);break;case'.':if(*lx=='U'||*lx=='L'||*lx=='S'||*lx=='T'||*lx=='C'){tk=mk2(TOK_STRMETH,lx,lx+1);lx++;}else if(isalpha(*lx)){tk=mk2(TOK_DOT,s,lx);}else{tk=mk2(TOK_UNK,s,lx);}break;default:tk=mk2(TOK_UNK,s,lx);break;}}
static void initLx(const char*s){lx=s;adv();}
static Node*MN(NT t,char*v){Node*n=malloc(sizeof(Node));n->t=t;n->v=v;n->n=0;n->cap=0;n->c=NULL;n->l=0;return n;}
static void ac(Node*p,Node*c){if(p->n>=p->cap){p->cap=p->cap?p->cap*2:4;p->c=realloc(p->c,p->cap*sizeof(Node*));}p->c[p->n++]=c;}
static Node*PE(void);static Node*PP(void);static Node*PT(void);
static Node*PP(void){if(tk.t==TOK_BINOP&&tk.v[1]==0&&(tk.v[0]=='-'||tk.v[0]=='+')){char*op=strdup(tk.v);adv();Node*o=PT();Node*b=MN(ND_BINOP,op);ac(b,o);return b;}switch(tk.t){case TOK_NUM:{Node*n=MN(ND_NUM,strdup(tk.v));adv();return n;}case TOK_STR:{Node*n=MN(ND_STR,strdup(tk.v));adv();return n;}case TOK_IDENT:{Node*n=MN(ND_IDENT,strdup(tk.v));adv();if(tk.t==TOK_LPAREN){adv();Node*c=MN(ND_CALL,strdup(n->v));ft(n);if(tk.t!=TOK_RPAREN){ac(c,PE());while(tk.t==TOK_COMMA){adv();ac(c,PE());}}if(tk.t!=TOK_RPAREN)fprintf(stderr,"error: expected ')'\n");else adv();return c;}return n;}case TOK_DEREF:{adv();if(tk.t!=TOK_IDENT){fprintf(stderr,"error: expected identifier after $\n");return MN(ND_IDENT,strdup(""));}Node*n=MN(ND_IDENT,strdup(tk.v));adv();if(tk.t==TOK_LPAREN){adv();Node*c=MN(ND_CALL,strdup(n->v));ft(n);if(tk.t!=TOK_RPAREN){ac(c,PE());while(tk.t==TOK_COMMA){adv();ac(c,PE());}}if(tk.t!=TOK_RPAREN)fprintf(stderr,"error: expected ')'\n");else adv();return c;}return n;}case TOK_LPAREN:{adv();Node*n=PE();if(tk.t!=TOK_RPAREN)fprintf(stderr,"error: expected ')'\n");else adv();return n;}default:fprintf(stderr,"error: unexpected token '%s'\n",tk.v);adv();return MN(ND_NUM,strdup("0"));}}
static Node*PT(void){Node*n=PP();while(tk.t==TOK_DOT){adv();if(tk.t!=TOK_IDENT){fprintf(stderr,"error: expected identifier after '.'\n");break;}size_t l=strlen(n->v)+strlen(tk.v)+2;char*f=malloc(l);sprintf(f,"%s.%s",n->v,tk.v);free(n->v);n->v=f;adv();}while(tk.t==TOK_LPAREN){adv();Node*c=MN(ND_CALL,n->v?strdup(n->v):strdup(""));ft(n);if(tk.t!=TOK_RPAREN){ac(c,PE());while(tk.t==TOK_COMMA){adv();ac(c,PE());}}if(tk.t!=TOK_RPAREN)fprintf(stderr,"error: expected ')'\n");else adv();n=c;}while(tk.t==TOK_STRMETH){Node*m=MN(ND_STRMETH,strdup(tk.v));adv();ac(m,n);n=m;}return n;}
static Node*PE(void){Node*n=PT();while(tk.t==TOK_BINOP){char*op=strdup(tk.v);adv();Node*r=PT();Node*b=MN(ND_BINOP,op);ac(b,n);ac(b,r);n=b;}return n;}
Node*parseStmt(const char*line){if(!line||!*line)return MN(ND_IDENT,strdup(""));const char*raw=line;while(*raw==' '||*raw=='\t')raw++;if(!*raw)return MN(ND_IDENT,strdup(""));char cmd=*raw;const char*rest=raw+1;while(*rest==' '||*rest=='\t')rest++;initLx(rest);switch(cmd){case'#':return MN(ND_IDENT,strdup(""));case'G':{Node*n=MN(ND_PRINTNL,strdup(""));Node*e=PE();if(e)ac(n,e);return n;}case'P':{Node*n=MN(ND_PRINT,strdup(""));Node*e=PE();if(e)ac(n,e);return n;}case'Q':return MN(ND_QUIT,strdup(""));case'X':{Node*n=MN(ND_ERROR,strdup(""));if(tk.t!=TOK_EOF){Node*e=PE();if(e)ac(n,e);}return n;}case'E':{if(tk.t==TOK_IDENT){Node*n=MN(ND_ASSIGN,strdup(""));Node*id=MN(ND_IDENT,strdup(tk.v));ac(n,id);adv();if(tk.t!=TOK_EOF){if(tk.t==TOK_EQ)adv();Node*e=PE();if(e)ac(n,e);}return n;}return PE();}case'D':{if(tk.t==TOK_STR){Node*n=MN(ND_DEL,strdup(tk.v));adv();return n;}Node*n=MN(ND_DELAY,strdup(""));Node*e=PE();if(e)ac(n,e);return n;}case'K':{Node*n=MN(ND_INPUT,strdup(""));if(tk.t==TOK_IDENT){ac(n,MN(ND_IDENT,strdup(tk.v)));adv();if(tk.t==TOK_STR){ac(n,MN(ND_STR,strdup(tk.v)));adv();if(tk.t==TOK_IDENT){ac(n,MN(ND_STR,strdup(tk.v)));adv();}}}else if(tk.t==TOK_STR){ac(n,MN(ND_STR,strdup(tk.v)));adv();if(tk.t==TOK_IDENT){ac(n,MN(ND_STR,strdup(tk.v)));adv();}}return n;}case'A':{Node*n=MN(ND_ARITH,strdup(""));if(tk.t==TOK_STR){ac(n,MN(ND_STR,strdup(tk.v)));adv();}if(tk.t==TOK_BINOP){n->v=strdup(tk.v);adv();}if(tk.t!=TOK_EOF){Node*e=PE();if(e)ac(n,e);}return n;}case'?':{Node*n=MN(ND_IF,strdup(""));Node*e=PE();if(e)ac(n,e);if(tk.t==TOK_IDENT&&strcmp(tk.v,"J")==0){adv();if(tk.t==TOK_IDENT){free(n->v);n->v=strdup(tk.v);adv();}}return n;}case':':return MN(ND_ELSE,strdup(""));case';':return MN(ND_ENDIF,strdup(""));case'@':{Node*n=MN(ND_WHILE,strdup(""));Node*e=PE();if(e)ac(n,e);return n;}case'&':return MN(ND_WEND,strdup(""));case'F':{if(tk.t==TOK_IDENT){char*fname=strdup(tk.v);adv();Node*n=MN(ND_FUNC,fname);if(tk.t==TOK_LPAREN){adv();while(tk.t==TOK_IDENT){ac(n,MN(ND_IDENT,strdup(tk.v)));adv();if(tk.t==TOK_COMMA)adv();}if(tk.t==TOK_RPAREN)adv();}return n;}return MN(ND_FUNC,strdup(""));}case'~':return MN(ND_ENDFN,strdup(""));case'R':{Node*n=MN(ND_RETURN,strdup(""));if(tk.t!=TOK_EOF){Node*e=PE();if(e)ac(n,e);}return n;}case'L':{Node*n=MN(ND_LABEL,strdup(""));if(tk.t==TOK_IDENT){free(n->v);n->v=strdup(tk.v);adv();}return n;}case'J':{Node*n=MN(ND_JUMP,strdup(""));if(tk.t==TOK_IDENT){free(n->v);n->v=strdup(tk.v);adv();}return n;}case'W':{Node*n=MN(ND_SWITCH,strdup(""));Node*e=PE();if(e)ac(n,e);return n;}case'V':{Node*n=MN(ND_CASE,strdup(""));Node*e=PE();if(e)ac(n,e);return n;}case'N':return MN(ND_DEF,strdup(""));case'Z':return MN(ND_ENDSW,strdup(""));case'T':return MN(ND_TRY,strdup(""));case'C':{Node*n=MN(ND_CATCH,strdup(""));if(tk.t==TOK_IDENT||tk.t==TOK_STR){free(n->v);n->v=strdup(tk.v);adv();}return n;}case'Y':return MN(ND_ENDTRY,strdup(""));case'O':{Node*n=MN(ND_FOR,strdup(""));if(tk.t==TOK_IDENT){ac(n,MN(ND_IDENT,strdup(tk.v)));adv();}if(tk.t!=TOK_EOF){ac(n,PT());if(tk.t!=TOK_EOF){ac(n,PT());if(tk.t!=TOK_EOF){ac(n,PT());}}}return n;}case'U':{Node*n=MN(ND_IMPORT,strdup(""));if(tk.t==TOK_STR||tk.t==TOK_IDENT){free(n->v);n->v=strdup(tk.v);adv();}return n;}case'S':{Node*n=MN(ND_STRREP,strdup(""));for(int i=0;i<3;i++){if(tk.t==TOK_STR){ac(n,MN(ND_STR,strdup(tk.v)));adv();}}return n;}default:{initLx(line);if(tk.t==TOK_IDENT){const char*saved_lx=lx;Tk2 saved_tk=tk;adv();if(tk.t==TOK_EQ){Node*n=MN(ND_ASSIGN,strdup(""));ac(n,MN(ND_IDENT,strdup(saved_tk.v)));adv();if(tk.t!=TOK_EOF){Node*e=PE();if(e)ac(n,e);}return n;}lx=saved_lx;tk=saved_tk;}return PE();}}}
Node*parse(const char*src){Node*p=MN(ND_PROG,strdup(""));char*b=strdup(src);char*txt=b;int line=1;char*lp=strtok(txt,"\n");while(lp){char*e=lp+strlen(lp);while(e>lp&&(e[-1]=='\r'))*--e=0;if(*lp){Node*n=parseStmt(lp);if(n){n->l=line;ac(p,n);}}line++;lp=strtok(NULL,"\n");}free(b);return p;}
const char*nn(NT t){switch(t){case ND_PROG:return"PROGRAM";case ND_NUM:return"NUM";case ND_STR:return"STR";case ND_IDENT:return"IDENT";case ND_BINOP:return"BINOP";case ND_PRINTNL:return"PRINT_NL";case ND_PRINT:return"PRINT";case ND_IF:return"IF";case ND_ELSE:return"ELSE";case ND_ENDIF:return"ENDIF";case ND_WHILE:return"WHILE";case ND_WEND:return"WEND";case ND_FOR:return"FOR";case ND_ASSIGN:return"ASSIGN";case ND_QUIT:return"QUIT";case ND_LABEL:return"LABEL";case ND_JUMP:return"JUMP";case ND_SWITCH:return"SWITCH";case ND_CASE:return"CASE";case ND_DEF:return"DEFAULT";case ND_ENDSW:return"ENDSWITCH";case ND_FUNC:return"FUNC";case ND_RETURN:return"RETURN";case ND_ENDFN:return"ENDFN";case ND_ERROR:return"ERROR";case ND_DELAY:return"DELAY";case ND_INPUT:return"INPUT";case ND_IMPORT:return"IMPORT";case ND_STRREP:return"STRREP";case ND_TRY:return"TRY";case ND_CATCH:return"CATCH";case ND_ENDTRY:return"ENDTRY";case ND_EXEC:return"EXEC";case ND_CEXEC:return"CEXEC";case ND_CLASS:return"CLASS";case ND_ARITH:return"ARITH";case ND_DEL:return"DEL";case ND_CALL:return"CALL";case ND_STRMETH:return"STRMETH";default:return"???";}}
void pt(Node*n,int d){if(!n)return;for(int i=0;i<d;i++)printf("  ");printf("%s",nn(n->t));if(n->v&&*n->v)printf(" [%s]",n->v);printf("\n");for(int i=0;i<n->n;i++)pt(n->c[i],d+1);}
void ft(Node*n){if(!n)return;for(int i=0;i<n->n;i++)ft(n->c[i]);free(n->c);free(n->v);free(n);}
